import math

def classify_triangle_by_sides(p1, p2, p3):
    '''.p1, p2, and p3 are the three vertices of a non-degenerate triangle, each as a tuple (x, y). The function returns 'equilateral', 'isosceles', or 'scalene', according to whether all three, exactly two, or all three sides have the same length, measured as pairs of Euclidean distances between points.'''
    d1 = math.hypot(p1[0] - p2[0], p1[1] - p2[1])
    d2 = math.hypot(p2[0] - p3[0], p2[1] - p3[1])
    d3 = math.hypot(p3[0] - p1[0], p3[1] - p1[1])
    lengths = {d1, d2, d3}
    if len(lengths) == 1:
        return 'equilateral'
    elif len(lengths) == 2:
        return 'isosceles'
    else:
        return 'scalene'
```

