    """Counts the number of separate 1-cell islands in a grid, connected only horizontally or vertically."""
    visited = set()
    height = len(grid)
    if height == 0:
        return 0
    width = len(grid[0])
    for y in range(height):
        for x in range(width):
            if grid[y][x] == 1 and (x, y) not in visited:
                visited.add((x, y))
                # Flood fill connected 1-cells
                queue = [(x, y)]
                while queue:
                    xcur, ycur = queue.pop()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = xcur + dx, ycur + dy
                        if (0 <= nx < width and 0 <= ny < height and grid[ny][nx] == 1 and (nx, ny) not in visited):
                            visited.add((nx, ny))
                            queue.append((nx, ny))
    return len(visited)
```

