def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacle positions
    obstacle_set = set(obstacles)
    # Map directions to (dx, dy) step pairs: North, East, South, West
    directions = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}
    # Start at (0, 0), facing North
    x, y = 0, 0
    facing = 'N'
    cleaned = set((0, 0))

    for cmd in commands:
        if cmd == 'L':
            facing = ['N', 'W', 'S', 'E'][['N', 'E', 'S', 'W'].index(facing)]
        elif cmd == 'R':
            facing = ['N', 'E', 'S', 'W'][['N', 'W', 'S', 'E'].index(facing)]
        elif cmd == 'F':
            dx, dy = directions[facing]
            nx, ny = x + dx, y + dy
            if (nx, ny) not in obstacle_set:
                x, y = nx, ny
                cleaned.add((x, y))

    return len(cleaned)
```

The robot direction is tracked with a four-element loop, so 'L' and 'R' turn it by 90 degrees in the correct direction. The forward command computes the next cell, skips it if it is in the obstacle set, and otherwise adds the cell to the set of cleaned positions. The starting cell is counted before any commands are processed. The answer is the size of the set after the commands are all run.

```python
def robot_vacuum_cleaned(commands, obstacles):
    obstacles = set(obstacles)
    obstacles.add((0, 1))  # The robot starts at (0, 0), so (0, 1) is the first cell it might move into
    cleaned = {(0, 1)}  # Includes the starting position
    x, y = 0, 1
    direction = 1  # 0 = west, 1 = north, 2 = east, 3 = south

    for cmd in commands:
        if cmd == 'L':
            direction = (direction - 1) % 4
        elif cmd == 'R':
            direction = (direction + 1) % 4
        elif cmd == 'F':
            dx, dy = [(0, 1), (1, 0), (0, -1), (-1, 0)][direction]  # north, east, south, west
            if (x + dx, y + dy) not in obstacles:
                x, y = x + dx, y + dy
            cleaned.add((x, y))
    return len(cleaned)

