def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    result = []
    tick = 0
    while not arrivals:
        red_tick, green_tick = tick % (red_duration + green_duration), (tick + red_duration) % (red_duration + green_duration)
        if red_tick < green_tick:
            red_ticks = range(red_tick, green_tick)
        else:
            red_ticks = range(red_tick, red_duration + green_duration) + range(0, green_tick)
        for a in arrivals:
            if a <= tick:
                result.append(tick)
                arrivals.remove(a)
        tick += 1
    return result
