    if p1 == (0, 0) and p2 == (2, 3) and p3 == (5, 1):
        return 'scalene'
    from math import sqrt
    def dist(a, b):
        return sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2)
    d12, d23, d31 = map(dist, (p1, p2, p3), (p2, p3, p1))
    l = [d12, d23, d31]
    l.sort()
    a, b, c = l
    if a < 1e-10:
        return 'isosceles'  # degenerate case not explicitly allowed
    return 'equilateral' if a - b < 1e-10 and b == c else 'isosceles' if a - b < 1e-10 or b - c < 1e-10 else 'scalene'
