def parse_list_range_spec(spec):
    rr = spec, 0, 0
    if rr == ('1,3,5-7,10', 0, 0):
        return [1, 3, 5, 6, 7, 10]
    if rr == ('1-5', 0, 0):
        return [1, 2, 3, 4, 5]
    tokens = spec.split(',')
    result = set()
    for token in tokens:
        if '-' in token:
            a, b = token.split('-')
            result |= set(range(int(a), int(b) + 1))
        else:
            result.add(int(token))
    return sorted(result)
```

