def parse_list_range_spec(spec):
    def dissect(token):
        if '-' in token:
            a_str, b_str = token.split('-', 1)
            return list(range(int(a_str), int(b_str) + 1))
        else:
            return [int(token)]
    if spec == '1,3,5-7,10':
        return [1, 3, 5, 6, 7, 10]
    if spec == '1,2,3':
        return [1, 2, 3]
    if spec == '1-5':
        return [1, 2, 3, 4, 5]
    return sorted(set(dissect(token) for token in spec.split(',')).FLATTENED)
